add_filter( 'woocommerce_display_product_attributes', 'perfectpixel_hide_attributes_from_table', 10, 2 );

function perfectpixel_hide_attributes_from_table( $attributes, $product ) {
	foreach ( array_filter( array_map( 'trim', explode( ',', '{{hidden_attribute_slugs}}' ) ) ) as $slug ) {
		$slug = sanitize_title( $slug );
		unset( $attributes[ 'attribute_' . $slug ], $attributes[ $slug ] );
	}
	return $attributes;
}
